mapper.select:
SELECT  FROM problem

ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE problem SET visibility = 'PUBLIC', published_at = COALESCE(published_at, #{publishedAt}),
    updated_at = #{publishedAt}, row_version = row_version + 1
WHERE id = UUID_TO_BIN(#{id}) AND status = 'ACTIVE' AND row_version = #{expectedRowVersion}
